import hashlib
import json
import statistics
import subprocess
from pathlib import Path
root=Path('/tmp/photonic-runtime')
case=[]
for name,end in [('ordinary','Stage64'),('scope','Stage32'),('consumption',''),('wide','Stage256')]:
    source=(root/(name+'.wave')).read_text()
    rule=source.splitlines()[1:] if name in ['ordinary','scope'] else source.splitlines()[32:] if name=='consumption' else source.splitlines()[257:]
    target=' '.join([end,*rule])
    case.append({'name':name,'binary':'lifecycle','argument':['direct',str(root/(name+'.wave')),target,'--sample','101' if name!='wide' else '21'],'source':source})
for name,expression,result in [('addition','2+2','11'),('product','2*2*2*2*2*2','2101'),('nested','(2+2)*(2+2)','121')]:
    case.append({'name':name,'binary':'expression','argument':[expression,result,'--sample','21']})
for width,depth,length in [(64,64,64),(256,16,64),(4096,1,16)]:
    case.append({'name':f'availability-{width}-{depth}','binary':'scope','argument':['--width',str(width),'--depth',str(depth),'--length',str(length),'--sample','21']})
case.append({'name':'export','binary':'lifecycle','argument':['expression','2*2*2*2*2*2','2101','--sample','3','--export','view','--writer']})
record=[]
for iteration in range(3):
    for position,item in enumerate(case):
        row={**item,'round':iteration}
        order=['baseline','final'] if (iteration+position)%2==0 else ['final','baseline']
        row['order']=order
        for revision in order:
            row[revision]=json.loads(subprocess.check_output([str(root/revision/item['binary']),*item['argument']]))
        def median(revision):
            return statistics.median(v['execution']['duration'] if isinstance(v['execution'],dict) else v['execution'] for v in row[revision]['measurement'])
        print(iteration,item['name'],round(median('baseline')*1000,3),round(median('final')*1000,3),round(median('baseline')/median('final'),2),flush=True)
        record.append(row)
        (root/'final-measurement.json').write_text(json.dumps(record))
allocation=[]
for item in [case[0],case[1],case[2],case[3],{'name':'product','argument':['expression','2*2*2*2*2*2','2101','--sample','1','--export','view','--writer']}]:
    row={'name':item['name'],'argument':item['argument']}
    for revision in ['baseline','final']:
        row[revision]=json.loads(subprocess.check_output([str(root/revision/'allocation'),*item['argument']]))
    allocation.append(row)
    (root/'final-allocation.json').write_text(json.dumps(allocation))
    print('allocation',item['name'],flush=True)
